diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..4b5a83b 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,29 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+test("RF-004: descuento por línea en porcentaje, redondeado al centavo", () => {
+  const f = calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 10 }]);
+  assert.equal(f.totalCentavos, 1800);
+  // sin descuento (o 0) no cambia nada; 100 % deja la línea en cero
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: 0 }]).totalCentavos, 1000);
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: 100 }]).totalCentavos, 0);
+  // redondeo al centavo: 3,33 Bs con 15 % = 283,05 centavos -> 283
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 333, descuentoPorcentaje: 15 }]).totalCentavos, 283);
+  // el descuento se aplica por línea, antes del total
+  const g = calcularFactura([
+    { cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 10 },
+    { cantidad: 1, precioUnitarioCentavos: 500 },
+  ]);
+  assert.equal(g.totalCentavos, 2300);
+  assert.ok(Number.isInteger(g.ivaCentavos) && Number.isInteger(g.netoCentavos));
+});
+
+test("RF-004: un descuento fuera de 0–100 se rechaza", () => {
+  for (const d of [-1, 100.5, 101, NaN, "10"]) {
+    assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: d }]), RangeError);
+  }
+});
